var CHEST_POS_ARR = [];
var getPosArr = function(num){
    let return_array = [];
    for (let i = 0; i < num; i++) {
        if (CHEST_POS_ARR.length > 0) {
            var arrIndex = Math.floor(Math.random() * CHEST_POS_ARR.length);
            return_array[i] = CHEST_POS_ARR[arrIndex];
            CHEST_POS_ARR.splice(arrIndex, 1);
        } else {
            break;
        }
    }
    return return_array;
}
