var _getRandomNum = function (start, end) {
    var l = end - start + 1;
    return ((0 | Math.random() * l) + start);
};

class GUser {
	constructor(userId, serverId) {
		this.userId = userId;
		this.serverId = serverId;
		this.state = 0;  // 0  初始值 1 在地图中 2 已离开地图 
 
		this.lastBlessTm = 0;
		this.getBlessNum = 0;		// 缓存获得的女神礼包的次数 （每次3秒)

		this.pickItemNum = 0;		// 宝箱拾取数目
	}
	checkBless(tmNow, player){
		if (this.state != 1) return ;
		if (tmNow.getTime() - this.lastBlessTm.getTime() >= consts.eGodness.ADDEXP_INTERVAL * 1000){	
			this.lastBlessTm = tmNow; 	
			this.getBlessNum++; 
		}

		// 如果满10次,累加入库
		if(this.getBlessNum >= 1){ 
			w2g.addGodnessExp(this.userId, this.getBlessNum * consts.eGodness.ADDEXP_INTERVAL, this.serverId, function(err,data){
				// 通知客户端更新数据
				//let player = this.worldMap.getPlayerByUid(this.userId);
				if(player){
					player.send("syncUserData", data);
				}
			});
			this.getBlessNum = 0;
		}

		return ;
	} 
	pickItem(){
		this.pickItemNum++;
	}
	getPickItem(){
		return this.pickItemNum;
	}
	join(){
		if (this.state != 1){	
			//console.log("Godness User " + this.userId + " join");
			this.state = 1;
			this.lastBlessTm = new Date(); 
		}
	}
	leave(){ // 离开不会从GUserList 删除,只是置状态
		//if (this.state != 2)
			//console.log("Godness User " + this.userId + " leave");
		this.state = 2;

		// 离线，女神经验入库
		if(this.getBlessNum > 0){ 
			w2g.addGodnessExp(this.userId, this.getBlessNum * consts.eGodness.ADDEXP_INTERVAL, this.serverId, (err,data) => {
				let player = playerManager.getPlayerByUid(this.userId);
				if(player){
					player.send("syncUserData", data);
				}
			});
			this.getBlessNum = 0;
		}
	} 
	isInGodnessActivty(){
		return this.state == 1;
	}
}

 class Godness{
 	constructor() {
 		// this.x = 23;
 		// this.y = 28; 
 		// this.r = 10; //16.5;	// 半径 330/40
 		this.cktimer = null;	// 检查活动的定时器, 一直存在 
 		this.activityTimer = null;  // 活动定时器,活动开始是启动，结束关闭
 		this.activityState = consts.eActivityStatus.init;  // eActivityStatus 活动状态 0 是初始 1 是开启 2 是关闭

 		this.lastSpawnChestTm = new Date();
 	}
 	getProfile(){
 		let endTime = this._getGodnessEndTime().getTime();
 		let tmNow = (new Date()).getTime();
 		let lastTime =  endTime - tmNow;
 		if(lastTime < 0) lastTime = 0;
 		var interval = parseInt(c_game.cityServerCfg[0].split(",")[2]);
 		let proto = {
 			ret : 0,
 			lastTime: lastTime,
 			interval: interval,
 			pickCd: consts.eGodness.PICK_CD,
 			maxItems:consts.eGodness.MAX_PICKNUM
 		};	
 		return proto;
 	}
 	_getGodnessStartTime() {
 		//return new Date().clearTime();//for test
 		let startTimeHours = parseInt(c_game.cityServerCfg[0].split(",")[0]);
 		let startTimeMinutes = parseInt(c_game.cityServerCfg[0].split(",")[1]);

 		//console.error("_getGodnessStartTime",startTimeHours, startTimeMinutes, c_game.cityServerCfg);
	    // var startTimeHours = consts.eGodness.BEGIN_HOUR;
	    // var startTimeMinutes = consts.eGodness.BEGIN_MINUTE;
	    let reTime = new Date().clearTime();
	    reTime.addHours(startTimeHours).addMinutes(startTimeMinutes);
	    return reTime;
	}
	_getGodnessEndTime() { 
		//return new Date().clearTime().addDays(1);//for test
 		let startTimeHours = parseInt(c_game.cityServerCfg[0].split(",")[0]);
 		let startTimeMinutes = parseInt(c_game.cityServerCfg[0].split(",")[1]);
 		let interval = parseInt(c_game.cityServerCfg[0].split(",")[2]);
	    let reTime = new Date().clearTime(); 
	    reTime.addHours(startTimeHours).addMinutes(startTimeMinutes).addSeconds(interval);
	    return reTime;
	}	
 	init(worldMap){ 
 		this.worldMap = worldMap;
 		this.cktimer = setInterval(() =>{
         	this.checkActivity(); 
    	},1000);
 	}
 	inActivityTime(tm){	//是否在活动时间里

 		if(tm.isAfter(this._getGodnessStartTime())&&tm.isBefore(this._getGodnessEndTime())){
        	return true;
    	} 		
     	return false;
 	}
 	checkActivity(){
 		//console.log("checkActivity");
 		let tmNow = new Date();
 		if (this.activityState == consts.eActivityStatus.init){
 			if(this.inActivityTime(tmNow)){
 				this.startActivity();
 			}
 		}else if(this.activityState == consts.eActivityStatus.running){
 			if(!this.inActivityTime(tmNow)){
 				this.endActivity();
 			}
 		}else if(this.activityState == consts.eActivityStatus.closed){
 			this.resetActivity();
 		}
 	}
 	join(player){	// 玩家加入
 		if(!this.inActivityTime(new Date())){
 			return false; 
 		}	

		if (!GUserList[player.getUserId()]){
			let userId = player.getUserId();
			let serverId = player.getServerId();
			let user = new GUser(userId, serverId);
			user.join();
			GUserList[player.getUserId()] = user;

			//this.boss.userIdList[userId][0];
			w2g.joinGodnessNum(userId, serverId);
		}else{
			GUserList[player.getUserId()].join();
		}
 		return true;
 	}
 	leave(userId){ 
 		GUserList[userId] && GUserList[userId].leave(); 
 	}
 	resetActivity(){ 
 		logger.info("godness resetActivity");
		this.activityState = consts.eActivityStatus.init;
 		GUserList = {}; 		
 	}
 	startActivity(){ 
 		logger.info("godness startActivity");
 		resetChestPosArr();
 		this.worldMap.syncGodnessBegin();
 		this.lastSpawnChestTm = new Date();
 		this.activityState = consts.eActivityStatus.running;
 		this.activityTimer = setInterval(() =>{
         	this.activityLoop(); 
    	},200);
 	}
 	endActivity(){ 
 		logger.info("godness endActivity");
 		this.activityState = consts.eActivityStatus.closed;
 		clearInterval(this.activityTimer);
 		this.activityTimer = null;
 		this.activityEndReward();
 		// 通知所有玩家活动结束 
 		this.worldMap.broadcast('syncGodnessEnd');

 		// 清除宝箱
 		chestManager.removeAllChest();
 	}
 	activityEndReward(){ 
 		
 	}
 	activityLoop(){
 		let tmNow = new Date();

 		// 刷宝箱 7,13
 		if (tmNow.getTime() - this.lastSpawnChestTm.getTime() >= consts.eGodness.SPAWN_CHEST_INTERVAL){

 			// 当前剩余宝箱数
 			let size = chestManager.size();
 			if (size < consts.eGodness.MAX_CHESTNUM){
 				let num = consts.eGodness.MAX_CHESTNUM - size;
 				if (num > 10) num = 10;
	 			let posArr = getPosArr(num);		// 刷新10个宝箱
	 			this.worldMap.spawnChests(posArr);
 			}

 			this.lastSpawnChestTm = tmNow;
 		}

 		// 宝箱check
 		chestManager.update(tmNow);

 		let keys = Object.keys(GUserList);
 		keys.forEach((userId) =>{
 			let user = GUserList[userId];
 			let player = playerManager.getPlayerByUid(userId);
 			if (player && player.getJoinGodness() && user.isInGodnessActivty()){
 				user.checkBless(tmNow, player);
 			}
 		});
 	}
 	getGUser(id){
 		return GUserList[id];
 	}
 }

 var godness = new Godness();
 module.exports.godness = godness; 
